# Print the makefiles a plain `make` invocation would read.
_choice_make_files() {
    local dir="$1"
    local -a names=()
    local name
    # $MAKEFILES is a whitespace-separated list, so split it on purpose.
    names+=(${MAKEFILES:-})
    if [[ -n "${argc_file:-}" ]]; then
        names+=("$argc_file")
    else
        names+=(GNUmakefile makefile Makefile)
    fi
    for name in "${names[@]}"; do
        if [[ "$name" == /* ]]; then
            printf '%s\n' "$name"
        else
            printf '%s\n' "$dir/$name"
        fi
    done
}

