# Parse makefiles. mode=target prints rule/phony targets with `##` descriptions;
# mode=var prints variable names. Read-only: no shell or recipe is executed.
_choice_make_parse() {
    local mode="$1"
    shift
    gawk -v mode="$mode" '
    BEGIN {
        comment = ""
        in_define = 0
    }
    function trim(s) {
        sub(/^[ \t]+/, "", s)
        sub(/[ \t]+$/, "", s)
        return s
    }
    function emit(name, desc) {
        if (name == "") return
        if (index(name, "%") || index(name, "$")) return
        if (name ~ /^\.[A-Z][A-Z_]*$/) return
        if (!(name in desc_of)) {
            order[++count] = name
            desc_of[name] = desc
        } else if (desc_of[name] == "" && desc != "") {
            desc_of[name] = desc
        }
    }
    {
        line = $0
        while (sub(/\\$/, "", line)) {
            if ((getline nxt) <= 0) break
            line = line " " nxt
        }
        if (in_define) {
            if (line ~ /^[ \t]*endef([ \t]|$)/) in_define = 0
            next
        }
        if (line ~ /^[ \t]*define([ \t]|$)/) { in_define = 1; next }
        if (line ~ /^[ \t]*$/) { comment = ""; next }
        if (line ~ /^[ \t]*##/) {
            sub(/^[ \t]*##[ \t]?/, "", line)
            comment = trim(line)
            next
        }
        if (line ~ /^[ \t]*#/) { comment = ""; next }
        if (line ~ /^\t/) next
        if (line ~ /^[ \t]*(export[ \t]+|override[ \t]+|private[ \t]+)*[A-Za-z_][A-Za-z0-9_.-]*[ \t]*(\?=|\+=|::=|:=|=)/) {
            if (mode == "var") {
                name = line
                sub(/[ \t]*(\?=|\+=|::=|:=|=).*$/, "", name)
                sub(/^[ \t]*(export[ \t]+|override[ \t]+|private[ \t]+)*/, "", name)
                name = trim(name)
                if (name != "" && name !~ /[ \t]/) print name
            }
            comment = ""
            next
        }
        pos = index(line, ":")
        if (pos == 0) { comment = ""; next }
        targets = trim(substr(line, 1, pos - 1))
        rest = substr(line, pos + 1)
        if (substr(rest, 1, 1) == ":") rest = substr(rest, 2)
        if (substr(rest, 1, 1) == "=") { comment = ""; next }
        desc = comment
        cp = index(rest, "##")
        if (cp > 0) {
            if (desc == "") desc = trim(substr(rest, cp + 2))
            rest = substr(rest, 1, cp - 1)
        }
        comment = ""
        if (mode == "var") next
        if (index(targets, "$") || index(targets, "%")) next
        nt = split(targets, tarr, /[ \t]+/)
        phony = 0
        special = 0
        for (i = 1; i <= nt; i++) {
            if (tarr[i] == ".PHONY") { phony = 1; continue }
            if (tarr[i] ~ /^\.[A-Z][A-Z_]*$/) { special = 1; continue }
            emit(tarr[i], desc)
        }
        if (phony && !special) {
            np = split(rest, parr, /[ \t]+/)
            for (i = 1; i <= np; i++) emit(parr[i], desc)
        }
    }
    END {
        for (i = 1; i <= count; i++) {
            name = order[i]
            if (desc_of[name] != "") printf "%s\t%s\n", name, desc_of[name]
            else print name
        }
    }
    ' "$@"
}

_choice_make_target() {
    local dir="${argc_directory:-.}"
    local -a files=()
    local file
    while IFS= read -r file; do
        if [[ -f "$file" && -r "$file" ]]; then
            files+=("$file")
        fi
    done < <(_choice_make_files "$dir")
    if (( ${#files[@]} == 0 )); then
        return 0
    fi
    if [[ "${ARGC_CWORD:-}" == *= ]]; then
        # Complete the variable name of a command-line override (VAR=value).
        printf '__argc_filter=\n'
        _choice_make_parse var "${files[@]}" | while IFS= read -r file; do
            printf '%s=\0\n' "$file"
        done
        return 0
    fi
    _choice_make_parse target "${files[@]}"
}
